import axios from "axios";

const fetchBookDetails = async (book) => {
  try {
    console.log("Fetching details for book:", book); // Debugging line
    const workKey = book.id
    console.log("teri ma: "); // Debugging line
    const res = await axios.get(`https://openlibrary.org${workKey}.json`);
    console.log("teri ma: ", res.data); // Debugging line
    book.description = res.data.description;
    return book;
  } catch (err) {
    console.error("Book details fetch failed", err);
    return book;
  }
};

export default fetchBookDetails;
